24	const mapArrayReadError = common.mapArrayReadError;
25	
26	const ChunkLookup = struct {
27	    chunk: *const ArrayRef,
28	    local_index: usize,
29	};
30	
31	fn lookupChunkAt(chunks: ChunkedArray, logical_index: usize) ?ChunkLookup {
32	    if (logical_index >= chunks.len()) return null;
33	
34	    var remaining = logical_index;
35	    var chunk_index: usize = 0;
36	    while (chunk_index < chunks.numChunks()) : (chunk_index += 1) {
37	        const chunk_ref = chunks.chunk(chunk_index);
38	        const chunk_len = chunk_ref.data().length;
39	        if (remaining < chunk_len) {
40	            return .{
41	                .chunk = chunk_ref,
42	                .local_index = remaining,
43	            };
44	        }
45	        remaining -= chunk_len;
46	    }
47	    return null;
48	}
49	
50	const PredicateDecision = enum {
51	    keep,
52	    drop,
53	    emit_null,
54	};
55	
56	fn appendOwnedArrayRef(
57	    allocator: std.mem.Allocator,
58	    pieces: *std.ArrayList(ArrayRef),
59	    piece: ArrayRef,
60	) KernelError!void {
61	    pieces.append(allocator, piece) catch {
62	        var owned = piece;
63	        owned.release();
64	        return error.OutOfMemory;
65	    };
66	}
67	
68	fn flushTakeContiguousRun(
69	    allocator: std.mem.Allocator,
70	    out_chunks: *std.ArrayList(ArrayRef),
71	    chunks: ChunkedArray,
72	    chunk_index: usize,
73	    run_start_local: usize,
74	    run_len: usize,
75	) KernelError!void {
76	    if (run_len == 0) return;
77	    const source = chunks.chunk(chunk_index).*;
78	    const source_len = source.data().length;
79	    const piece = if (run_start_local == 0 and run_len == source_len)
80	        source.retain()
81	    else
82	        source.slice(run_start_local, run_len) catch |err| return mapArrayReadError(err);
83	    try appendOwnedArrayRef(allocator, out_chunks, piece);
84	}
85	
86	fn flushTakeNullRun(
87	    allocator: std.mem.Allocator,
88	    out_chunks: *std.ArrayList(ArrayRef),
89	    out_type: DataType,
90	    null_run_len: usize,
91	) KernelError!void {
92	    if (null_run_len == 0) return;
93	    const nulls = try builders.buildNullLikeArray(allocator, out_type, null_run_len);
94	    try appendOwnedArrayRef(allocator, out_chunks, nulls);
95	}
96	
97	fn datumTakeChunkedNullable(
98	    allocator: std.mem.Allocator,
99	    chunks: ChunkedArray,
100	    out_type: DataType,
101	    indices: []const ?usize,
102	) KernelError!Datum {
103	    if (indices.len == 0) {
104	        return Datum.fromChunked(chunks.slice(allocator, 0, 0) catch |err| return common.mapChunkedError(err));
105	    }
106	
107	    var out_chunks: std.ArrayList(ArrayRef) = .empty;
108	    errdefer {
109	        for (out_chunks.items) |*chunk| chunk.release();
110	        out_chunks.deinit(allocator);
111	    }
112	
113	    var non_null_count: usize = 0;
114	    for (indices) |idx| {
115	        if (idx != null) {
116	            non_null_count = std.math.add(usize, non_null_count, 1) catch return error.Overflow;
117	        }
118	    }
119	
120	    var resolved: []accessors.ChunkLocalIndex = &[_]accessors.ChunkLocalIndex{};
121	    defer if (resolved.len > 0) allocator.free(resolved);
122	    var non_null_indices: []usize = &[_]usize{};
123	    if (non_null_count > 0) {
124	        non_null_indices = allocator.alloc(usize, non_null_count) catch return error.OutOfMemory;
125	        defer allocator.free(non_null_indices);
126	
127	        var fill_i: usize = 0;
128	        for (indices) |idx| {
129	            if (idx) |logical| {
130	                non_null_indices[fill_i] = logical;
131	                fill_i += 1;
132	            }
133	        }
134	        resolved = try accessors.chunkedResolveLogicalIndices(allocator, chunks, non_null_indices);
135	    }
136	
137	    var run_active = false;
138	    var run_chunk_index: usize = 0;
139	    var run_start_local: usize = 0;
140	    var run_len: usize = 0;
141	    var null_run_len: usize = 0;
142	    var resolved_i: usize = 0;
143	
144	    for (indices) |maybe_index| {
145	        if (maybe_index == null) {
146	            if (run_active) {
147	                try flushTakeContiguousRun(allocator, &out_chunks, chunks, run_chunk_index, run_start_local, run_len);
148	                run_active = false;
149	                run_len = 0;
150	            }
151	            null_run_len = std.math.add(usize, null_run_len, 1) catch return error.Overflow;
152	            continue;
153	        }
154	
155	        if (resolved_i >= resolved.len) return error.InvalidInput;
156	        const located = resolved[resolved_i];
157	        resolved_i += 1;
158	
159	        if (null_run_len > 0) {
160	            try flushTakeNullRun(allocator, &out_chunks, out_type, null_run_len);
161	            null_run_len = 0;
162	        }
163	
164	        if (!run_active) {
165	            run_active = true;
166	            run_chunk_index = located.chunk_index;
167	            run_start_local = located.index_in_chunk;
168	            run_len = 1;
169	            continue;
170	        }
171	
172	        const expected_next = run_start_local + run_len;
173	        if (located.chunk_index == run_chunk_index and located.index_in_chunk == expected_next) {
174	            run_len = std.math.add(usize, run_len, 1) catch return error.Overflow;
175	            continue;
176	        }
177	
178	        try flushTakeContiguousRun(allocator, &out_chunks, chunks, run_chunk_index, run_start_local, run_len);
179	        run_chunk_index = located.chunk_index;
180	        run_start_local = located.index_in_chunk;
181	        run_len = 1;
182	    }
183	
184	    if (resolved_i != resolved.len) return error.InvalidInput;
185	
186	    if (run_active) {
187	        try flushTakeContiguousRun(allocator, &out_chunks, chunks, run_chunk_index, run_start_local, run_len);
188	    }
189	    if (null_run_len > 0) {
190	        try flushTakeNullRun(allocator, &out_chunks, out_type, null_run_len);
191	    }
192	
193	    const out = ChunkedArray.init(allocator, out_type, out_chunks.items) catch |err| return common.mapChunkedError(err);
194	    for (out_chunks.items) |*chunk| chunk.release();
195	    out_chunks.deinit(allocator);
196	    return Datum.fromChunked(out);
197	}
198	
199	/// Direct gather for fixed-width and boolean arrays: output buffers are allocated once, every
200	/// slot copies its value without a branch, and validity is packed 8 rows per byte (gatherBits).
201	/// `indices` is `[]const ?usize` (null = null row) or dense `[]const usize` / `[]const u32`.
202	/// Returns null for layouts it does not handle so callers fall back to slice+concat.
203	fn takeFixedWidthArray(
204	    allocator: std.mem.Allocator,
205	    src: *const array_mod.ArrayData,
206	    indices: anytype,
207	) KernelError!?ArrayRef {
208	    const byte_width: usize = switch (src.data_type) {
209	        .bool => 0,
210	        .uint8, .int8 => 1,
211	        .uint16, .int16, .half_float => 2,
212	        .uint32, .int32, .float, .date32, .time32, .interval_months, .decimal32 => 4,
213	        .uint64, .int64, .double, .date64, .time64, .timestamp, .duration, .interval_day_time, .decimal64 => 8,
214	        .decimal128, .interval_month_day_nano => 16,
215	        .decimal256 => 32,
216	        else => return null,
217	    };
218	    if (src.buffers.len != 2) return null;
219	    const is_bool = byte_width == 0;
220	    const src_bytes = src.buffers[1].data;
221	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
222	    const src_need = if (is_bool) bitmap.byteLength(src_end) else std.math.mul(usize, src_end, byte_width) catch return error.Overflow;
223	    if (src_bytes.len < src_need) return error.InvalidInput;
224	    const src_validity = try validityBytes(src, src_end);
225	    try checkIndices(indices, src.length);
226	
227	    const out_len = indices.len;
228	    const values_len = if (is_bool) bitmap.byteLength(out_len) else out_len * byte_width;
229	    // Bool values are OR-ed bits (need zeroed memory); fixed-width slots are all written below.
230	    var values = (if (is_bool) buffer.OwnedBuffer.init(allocator, values_len) else buffer.OwnedBuffer.initUninit(allocator, values_len)) catch return error.OutOfMemory;
231	    errdefer values.deinit();
232	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
233	    errdefer validity.deinit();
234	
235	    const null_count = out_len - gatherBits(validity.data, src_validity, src.offset, indices);
236	    if (is_bool) {
237	        _ = gatherBits(values.data, src_bytes, src.offset, indices);
238	    } else switch (byte_width) {
239	        inline 1, 2, 4, 8, 16, 32 => |w| {
240	            const E = [w]u8;
241	            const s = std.mem.bytesAsSlice(E, src_bytes[src.offset * w ..][0 .. src.length * w]);
242	            const d = std.mem.bytesAsSlice(E, values.data[0..values_len]);
243	            for (indices, d) |m, *o| o.* = if (@as(?usize, m)) |j| s[j] else @splat(0);
244	        },
245	        else => unreachable,
246	    }
247	
248	    var buffers: [2]buffer.SharedBuffer = undefined;
249	    buffers[0] = if (null_count == 0) blk: {
250	        validity.deinit();
251	        break :blk buffer.SharedBuffer.empty;
252	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
253	    errdefer buffers[0].release();
254	    buffers[1] = values.toShared(values_len) catch return error.OutOfMemory;
255	    errdefer buffers[1].release();
256	
257	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
258	        .data_type = src.data_type,
259	        .length = out_len,
260	        .null_count = null_count,
261	        .buffers = buffers[0..],
262	    }) catch return error.OutOfMemory;
263	}
264	
265	/// The source validity bytes (null when there is no bitmap), checked to cover `src_end` bits.
266	fn validityBytes(src: *const array_mod.ArrayData, src_end: usize) KernelError!?[]const u8 {
267	    const v = src.validity() orelse return null;
268	    if (v.data.len < bitmap.byteLength(src_end)) return error.InvalidInput;
269	    return v.data;
270	}
271	
272	/// Index slices without null entries (`[]const usize`, `[]const u32`).
273	fn isDense(comptime I: type) bool {
274	    return I == []const usize or I == []const u32;
275	}
276	
277	/// Every non-null index must be < len. Dense slices use a max-reduce, which vectorizes.
278	fn checkIndices(indices: anytype, len: usize) KernelError!void {
279	    const I = @TypeOf(indices);
280	    if (comptime isDense(I)) {
281	        if (indices.len > 0 and std.mem.max(@typeInfo(I).pointer.child, indices) >= len) return error.InvalidInput;
282	    } else for (indices) |maybe| if (maybe) |idx| {
283	        if (idx >= len) return error.InvalidInput;
284	    };
285	}
286	
287	/// Bit i of zeroed `dst` = indices[i] is non-null and bit `offset + indices[i]` of `src` is set
288	/// (`src == null` means all set). 8 indices per output byte, no data-dependent branch
289	/// (arrow-rs take_bits). Returns the number of set bits. Callers bounds-check indices and `src`.
290	fn gatherBits(dst: []u8, src: ?[]const u8, offset: usize, indices: anytype) usize {
291	    var set: usize = 0;
292	    var i: usize = 0;
293	    while (i + 8 <= indices.len) : (i += 8) {
294	        var byte: u8 = 0;
295	        inline for (0..8) |k| byte |= bitOf(src, offset, indices[i + k]) << k;
296	        dst[i >> 3] = byte;
297	        set += @popCount(byte);
298	    }
299	    if (i < indices.len) {
300	        var byte: u8 = 0;
301	        for (indices[i..], 0..) |m, k| byte |= bitOf(src, offset, m) << @intCast(k);
302	        dst[i >> 3] = byte;
303	        set += @popCount(byte);
304	    }
305	    return set;
306	}
307	
308	inline fn bitOf(src: ?[]const u8, offset: usize, maybe: anytype) u8 {
309	    const idx = @as(?usize, maybe) orelse return 0;
310	    const s = src orelse return 1;
311	    const j = offset + idx;
312	    return (s[j >> 3] >> @intCast(j & 7)) & 1;
313	}
314	
315	fn validAt(src_validity: ?bitmap.ValidityBitmap, j: usize) bool {
316	    const v = src_validity orelse return true;
317	    return bitmap.bitIsSet(v.data, j);
318	}
319	
320	/// Value range of row `j` (physical index) in an offsets buffer; `limit` bounds the end.
321	fn offsetRange(comptime T: type, offsets: []const T, j: usize, limit: usize) KernelError![2]usize {
322	    const lo = std.math.cast(usize, offsets[j]) orelse return error.InvalidInput;
323	    const hi = std.math.cast(usize, offsets[j + 1]) orelse return error.InvalidInput;
324	    if (hi < lo or hi > limit) return error.InvalidInput;
325	    return .{ lo, hi };
326	}
327	
328	/// Direct gather for string/binary (i32 or i64 offsets): pass 1 bounds-checks offsets and sizes
329	/// the value buffer, pass 2 copies offsets + bytes, validity is packed by gatherBits.
330	/// Null source rows keep their bytes (usually none), like arrow-rs. Returns null for other layouts.
331	fn takeBinaryArray(
332	    comptime T: type,
333	    allocator: std.mem.Allocator,
334	    src: *const array_mod.ArrayData,
335	    indices: anytype,
336	) KernelError!?ArrayRef {
337	    if (src.buffers.len != 3) return null;
338	    const offsets = src.buffers[1].typedSlice(T) catch return error.InvalidInput;
339	    const bytes = src.buffers[2].data;
340	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
341	    if (offsets.len <= src_end) return error.InvalidInput;
342	    const src_validity = try validityBytes(src, src_end);
343	    try checkIndices(indices, src.length);
344	
345	    var total: usize = 0;
346	    for (indices) |maybe| {
347	        const idx: usize = @as(?usize, maybe) orelse continue;
348	        const r = try offsetRange(T, offsets, src.offset + idx, bytes.len);
349	        total = std.math.add(usize, total, r[1] - r[0]) catch return error.Overflow;
350	    }
351	    if (total > std.math.maxInt(T)) return error.Overflow;
352	
353	    const out_len = indices.len;
354	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, (out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
355	    errdefer out_offsets.deinit();
356	    // 16 bytes of slack so short values move as one fixed 16-byte copy (copyShort).
357	    var out_bytes = buffer.OwnedBuffer.initUninit(allocator, total + 16) catch return error.OutOfMemory;
358	    errdefer out_bytes.deinit();
359	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
360	    errdefer validity.deinit();
361	
362	    const o = out_offsets.typedSlice(T);
363	    o[0] = 0;
364	    var pos: usize = 0;
365	    for (indices, 0..) |maybe, i| {
366	        if (@as(?usize, maybe)) |idx| {
367	            const j = src.offset + idx;
368	            const lo: usize = @intCast(offsets[j]);
369	            const n: usize = @intCast(offsets[j + 1] - offsets[j]);
370	            copyShort(out_bytes.data[pos..], bytes, lo, n);
371	            pos += n;
372	        }
373	        o[i + 1] = @intCast(pos);
374	    }
375	    const null_count = out_len - gatherBits(validity.data, src_validity, src.offset, indices);
376	
377	    var buffers: [3]buffer.SharedBuffer = undefined;
378	    buffers[0] = if (null_count == 0) blk: {
379	        validity.deinit();
380	        break :blk buffer.SharedBuffer.empty;
381	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
382	    errdefer buffers[0].release();
383	    buffers[1] = out_offsets.toShared((out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
384	    errdefer buffers[1].release();
385	    buffers[2] = out_bytes.toShared(total) catch return error.OutOfMemory;
386	    errdefer buffers[2].release();
387	
388	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
389	        .data_type = src.data_type,
390	        .length = out_len,
391	        .null_count = null_count,
392	        .buffers = buffers[0..],
393	    }) catch return error.OutOfMemory;
394	}
395	
396	/// Copies `src[lo..][0..n]` to the front of `dst`. Values of at most 16 bytes move as one fixed
397	/// 16-byte load/store when both sides have room; `dst` bytes past `n` are scratch.
398	inline fn copyShort(dst: []u8, src: []const u8, lo: usize, n: usize) void {
399	    if (n <= 16 and lo + 16 <= src.len and dst.len >= 16) {
400	        dst[0..16].* = src[lo..][0..16].*;
401	    } else @memcpy(dst[0..n], src[lo..][0..n]);
402	}
403	
404	/// Direct gather for list/large_list: rebuilds offsets + validity and takes the child once
405	/// with the expanded child indices (recursing into the fast kernels). Returns null for other layouts.
406	fn takeListArray(
407	    comptime T: type,
408	    allocator: std.mem.Allocator,
409	    src: *const array_mod.ArrayData,
410	    indices: anytype,
411	) KernelError!?ArrayRef {
412	    if (src.buffers.len != 2 or src.children.len != 1) return null;
413	    const offsets = src.buffers[1].typedSlice(T) catch return error.InvalidInput;
414	    const child = src.children[0];
415	    const child_len = child.data().length;
416	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
417	    if (offsets.len <= src_end) return error.InvalidInput;
418	    const src_validity = src.validity();
419	
420	    var total: usize = 0;
421	    var null_count: usize = 0;
422	    for (indices) |maybe| {
423	        const idx: usize = @as(?usize, maybe) orelse {
424	            null_count += 1;
425	            continue;
426	        };
427	        if (idx >= src.length) return error.InvalidInput;
428	        const j = src.offset + idx;
429	        if (!validAt(src_validity, j)) {
430	            null_count += 1;
431	            continue;
432	        }
433	        const r = try offsetRange(T, offsets, j, child_len);
434	        total = std.math.add(usize, total, r[1] - r[0]) catch return error.Overflow;
435	    }
436	    if (total > std.math.maxInt(T)) return error.Overflow;
437	
438	    const child_indices = allocator.alloc(usize, total) catch return error.OutOfMemory;
439	    defer allocator.free(child_indices);
440	    const out_len = indices.len;
441	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, (out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
442	    errdefer out_offsets.deinit();
443	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
444	    errdefer validity.deinit();
445	
446	    const o = out_offsets.typedSlice(T);
447	    o[0] = 0;
448	    var pos: usize = 0;
449	    for (indices, 0..) |maybe, i| {
450	        if (@as(?usize, maybe)) |idx| {
451	            const j = src.offset + idx;
452	            if (validAt(src_validity, j)) {
453	                const lo: usize = @intCast(offsets[j]);
454	                const hi: usize = @intCast(offsets[j + 1]);
455	                for (child_indices[pos..][0 .. hi - lo], lo..) |*ci, k| ci.* = k;
456	                pos += hi - lo;
457	                bitmap.setBit(validity.data, i);
458	            }
459	        }
460	        o[i + 1] = @intCast(pos);
461	    }
462	
463	    var taken = try datumTakeArrayLikeNullable(allocator, Datum.fromArray(child), child.data().data_type, @as([]const usize, child_indices));
464	    if (taken != .array) {
465	        taken.release();
466	        return error.InvalidInput;
467	    }
468	    const children = allocator.alloc(ArrayRef, 1) catch {
469	        taken.release();
470	        return error.OutOfMemory;
471	    };
472	    children[0] = taken.array;
473	    errdefer {
474	        children[0].release();
475	        allocator.free(children);
476	    }
477	
478	    var buffers: [2]buffer.SharedBuffer = undefined;
479	    buffers[0] = if (null_count == 0) blk: {
480	        validity.deinit();
481	        break :blk buffer.SharedBuffer.empty;
482	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
483	    errdefer buffers[0].release();
484	    buffers[1] = out_offsets.toShared((out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
485	    errdefer buffers[1].release();
486	
487	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
488	        .data_type = src.data_type,
489	        .length = out_len,
490	        .null_count = null_count,
491	        .buffers = buffers[0..],
492	        .children = children,
493	    }) catch return error.OutOfMemory;
494	}
