496	fn datumTakeArrayLikeNullable(
497	    allocator: std.mem.Allocator,
498	    datum: Datum,
499	    out_type: DataType,
500	    indices: anytype,
501	) KernelError!Datum {
502	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
503	    if (datum == .array) {
504	        const src = datum.array.data();
505	        const fast = switch (src.data_type) {
506	            .string, .binary => try takeBinaryArray(i32, allocator, src, indices),
507	            .large_string, .large_binary => try takeBinaryArray(i64, allocator, src, indices),
508	            .list => try takeListArray(i32, allocator, src, indices),
509	            .large_list => try takeListArray(i64, allocator, src, indices),
510	            else => try takeFixedWidthArray(allocator, src, indices),
511	        };
512	        if (fast) |out| return Datum.fromArray(out);
513	    }
514	
515	    var pieces: std.ArrayList(ArrayRef) = .empty;
516	    defer {
517	        for (pieces.items) |*piece| piece.release();
518	        pieces.deinit(allocator);
519	    }
520	    try pieces.ensureTotalCapacity(allocator, indices.len);
521	
522	    for (indices) |choice| {
523	        const piece = if (@as(?usize, choice)) |idx|
524	            try accessors.datumElementArrayAt(allocator, datum, idx)
525	        else
526	            try builders.buildNullLikeArray(allocator, out_type, 1);
527	        pieces.appendAssumeCapacity(piece);
528	    }
529	
530	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
531	    return Datum.fromArray(out);
532	}
