534	fn predicateDecisionAt(predicate: Datum, logical_index: usize, options: FilterOptions) KernelError!PredicateDecision {
535	    return switch (predicate) {
536	        .scalar => |s| blk: {
537	            if (s.data_type != .bool) break :blk error.InvalidInput;
538	            if (s.isNull()) break :blk if (options.drop_nulls) .drop else .emit_null;
539	            break :blk if (s.value.bool) .keep else .drop;
540	        },
541	        .array => |arr| blk: {
542	            if (arr.data().data_type != .bool) break :blk error.InvalidInput;
543	            if (logical_index >= arr.data().length) break :blk error.InvalidInput;
544	            if (arr.data().isNull(logical_index)) break :blk if (options.drop_nulls) .drop else .emit_null;
545	            const bool_array = array_mod.BooleanArray{ .data = arr.data() };
546	            const keep = bool_array.value(logical_index) catch |err| return mapArrayReadError(err);
547	            break :blk if (keep) .keep else .drop;
548	        },
549	        .chunked => |chunks| blk: {
550	            if (chunks.dataType() != .bool) break :blk error.InvalidInput;
551	            const located = lookupChunkAt(chunks, logical_index) orelse break :blk error.InvalidInput;
552	            if (located.chunk.data().isNull(located.local_index)) break :blk if (options.drop_nulls) .drop else .emit_null;
553	            const bool_array = array_mod.BooleanArray{ .data = located.chunk.data() };
554	            const keep = bool_array.value(located.local_index) catch |err| return mapArrayReadError(err);
555	            break :blk if (keep) .keep else .drop;
556	        },
557	    };
558	}
