560	const SelectionByte = struct { emit: u8, valid: u8 };
561	
562	/// Rows `row .. row+8` of a bool predicate: which rows emit an entry and which of those are valid.
563	fn selectionByte(values: []const u8, validity: []const u8, bit: usize, rows_left: usize, drop_nulls: bool) SelectionByte {
564	    const tail_mask: u8 = if (rows_left >= 8) 0xFF else (@as(u8, 1) << @intCast(rows_left)) - 1;
565	    const valid = if (validity.len > 0) bitmap.byteAtBit(validity, bit) else 0xFF;
566	    var emit = bitmap.byteAtBit(values, bit) & valid;
567	    if (!drop_nulls) emit |= ~valid;
568	    return .{ .emit = emit & tail_mask, .valid = valid };
569	}
