571	/// Appends selections for rows [0, len) of a bool predicate array, 8 rows per step.
572	/// `base` is the logical index of the predicate's row 0.
573	fn appendBoolSelections(
574	    allocator: std.mem.Allocator,
575	    selections: anytype,
576	    pred: *const array_mod.ArrayData,
577	    len: usize,
578	    base: usize,
579	    options: FilterOptions,
580	) KernelError!void {
581	    if (pred.buffers.len < 2) return error.InvalidInput;
582	    const values = pred.buffers[1].data;
583	    const end = std.math.add(usize, pred.offset, len) catch return error.Overflow;
584	    if (bitmap.byteLength(end) > values.len) return error.InvalidInput;
585	    const validity: []const u8 = if (pred.validity()) |v| v.data else &.{};
586	    if (validity.len > 0 and bitmap.byteLength(end) > validity.len) return error.InvalidInput;
587	
588	    var count: usize = 0;
589	    var row: usize = 0;
590	    while (row < len) : (row += 8) {
591	        count += @popCount(selectionByte(values, validity, pred.offset + row, len - row, options.drop_nulls).emit);
592	    }
593	    try selections.ensureTotalCapacityPrecise(allocator, selections.items.len + count);
594	
595	    row = 0;
596	    while (row < len) : (row += 8) {
597	        const sb = selectionByte(values, validity, pred.offset + row, len - row, options.drop_nulls);
598	        var emit = sb.emit;
599	        while (emit != 0) : (emit &= emit - 1) {
600	            const bit: u3 = @intCast(@ctz(emit));
601	            const is_valid = (sb.valid >> bit) & 1 != 0;
602	            if (@TypeOf(selections.items[0]) != ?usize) {
603	                std.debug.assert(is_valid); // dense lists are only built with drop_nulls
604	                selections.appendAssumeCapacity(@intCast(base + row + bit));
605	            } else selections.appendAssumeCapacity(if (is_valid) base + row + bit else null);
606	        }
607	    }
608	}
