610	/// Build nullable selection indices from a boolean predicate.
611	///
612	/// `keep` emits the logical input index, `drop` emits nothing, and `emit_null`
613	/// emits `null` to preserve output row count for null-predicate semantics.
614	pub fn datumFilterSelectionIndices(
615	    allocator: std.mem.Allocator,
616	    predicate: Datum,
617	    logical_len: usize,
618	    options: FilterOptions,
619	) KernelError![]?usize {
620	    var selections: std.ArrayList(?usize) = .empty;
621	    defer selections.deinit(allocator);
622	
623	    switch (predicate) {
624	        .array => |arr| {
625	            if (arr.data().data_type != .bool) return error.InvalidInput;
626	            if (logical_len > arr.data().length) return error.InvalidInput;
627	            try appendBoolSelections(allocator, &selections, arr.data(), logical_len, 0, options);
628	        },
629	        .chunked => |chunks| {
630	            if (chunks.dataType() != .bool) return error.InvalidInput;
631	            var done: usize = 0;
632	            for (chunks.chunks()) |chunk| {
633	                if (done == logical_len) break;
634	                const take = @min(chunk.data().length, logical_len - done);
635	                try appendBoolSelections(allocator, &selections, chunk.data(), take, done, options);
636	                done += take;
637	            }
638	            if (done != logical_len) return error.InvalidInput;
639	        },
640	        .scalar => {
641	            var i: usize = 0;
642	            while (i < logical_len) : (i += 1) {
643	                switch (try predicateDecisionAt(predicate, i, options)) {
644	                    .drop => {},
645	                    .keep => try selections.append(allocator, i),
646	                    .emit_null => try selections.append(allocator, null),
647	                }
648	            }
649	        },
650	    }
651	    return selections.toOwnedSlice(allocator);
652	}
