654	/// Gather/take rows from a datum according to logical indices.
655	///
656	/// For chunked inputs this helper preserves chunked output and avoids forcing
657	/// concat pre-normalization.
658	pub fn datumTake(datum: Datum, indices: []const usize) KernelError!Datum {
659	    const allocator = common.inferDatumAllocator(datum) orelse std.heap.page_allocator;
660	    const out_type = datum.dataType();
661	
662	    if (indices.len == 0) {
663	        return switch (datum) {
664	            .chunked => |chunks| Datum.fromChunked(chunks.slice(allocator, 0, 0) catch |err| return common.mapChunkedError(err)),
665	            else => builders.datumBuildEmptyLikeWithAllocator(allocator, out_type),
666	        };
667	    }
668	
669	    return switch (datum) {
670	        .chunked => |chunks| blk: {
671	            var nullable = allocator.alloc(?usize, indices.len) catch break :blk error.OutOfMemory;
672	            defer allocator.free(nullable);
673	            for (indices, 0..) |index, i| nullable[i] = index;
674	            break :blk try datumTakeChunkedNullable(allocator, chunks, out_type, nullable);
675	        },
676	        else => datumTakeArrayLikeNullable(allocator, datum, out_type, indices),
677	    };
678	}
