680	/// Gather/take rows with nullable indices where `null` emits an all-null row.
681	///
682	/// For chunked inputs this helper preserves chunked output and avoids forcing
683	/// concat pre-normalization.
684	pub fn datumTakeNullable(datum: Datum, indices: []const ?usize) KernelError!Datum {
685	    const allocator = common.inferDatumAllocator(datum) orelse std.heap.page_allocator;
686	    const out_type = datum.dataType();
687	    return switch (datum) {
688	        .chunked => |chunks| datumTakeChunkedNullable(allocator, chunks, out_type, indices),
689	        else => datumTakeArrayLikeNullable(allocator, datum, out_type, indices),
690	    };
691	}
