693	/// Row-wise selection primitive shared by choose/case_when/filter style operators.
694	///
695	/// `indices[i]` selects which entry in `values` contributes output row `i`.
696	/// Each candidate value may be array/chunked/scalar (scalar broadcasts).
697	pub fn datumSelect(indices: []const usize, values: []const Datum) KernelError!Datum {
698	    if (values.len == 0) return error.InvalidArity;
699	    if (!sameDataTypes(values)) return error.InvalidInput;
700	
701	    const output_len = try inferNaryExecLen(values);
702	    if (indices.len != output_len) return error.InvalidInput;
703	
704	    const allocator = common.inferDatumsAllocator(values);
705	    const out_type = values[0].dataType();
706	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
707	
708	    var pieces: std.ArrayList(ArrayRef) = .empty;
709	    defer {
710	        for (pieces.items) |*piece| piece.release();
711	        pieces.deinit(allocator);
712	    }
713	    try pieces.ensureTotalCapacity(allocator, indices.len);
714	
715	    for (indices, 0..) |choice, logical_index| {
716	        if (choice >= values.len) return error.InvalidInput;
717	        const piece = try accessors.datumElementArrayAt(allocator, values[choice], logical_index);
718	        pieces.appendAssumeCapacity(piece);
719	    }
720	
721	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
722	    return Datum.fromArray(out);
723	}
