728	pub fn datumSelectNullable(indices: []const ?usize, values: []const Datum) KernelError!Datum {
729	    if (values.len == 0) return error.InvalidArity;
730	    if (!sameDataTypes(values)) return error.InvalidInput;
731	
732	    const output_len = try inferNaryExecLen(values);
733	    if (indices.len != output_len) return error.InvalidInput;
734	
735	    const allocator = common.inferDatumsAllocator(values);
736	    const out_type = values[0].dataType();
737	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
738	
739	    var pieces: std.ArrayList(ArrayRef) = .empty;
740	    defer {
741	        for (pieces.items) |*piece| piece.release();
742	        pieces.deinit(allocator);
743	    }
744	    try pieces.ensureTotalCapacity(allocator, indices.len);
745	
746	    for (indices, 0..) |choice, logical_index| {
747	        const piece = if (choice) |idx| blk: {
748	            if (idx >= values.len) return error.InvalidInput;
