758	/// Chunk-aware filter helper for array/chunked/scalar datums with bool predicates.
759	///
760	/// This helper composes `datumFilterSelectionIndices` + `datumTakeNullable`,
761	/// preserving chunked output when the input datum is chunked.
762	pub fn datumFilterChunkAware(datum: Datum, predicate: Datum, options: FilterOptions) KernelError!Datum {
763	    const input_len = try inferBinaryExecLen(datum, predicate);
764	    const allocator = common.inferDatumsAllocator(&[_]Datum{ datum, predicate });
765	    const selections = try datumFilterSelectionIndices(allocator, predicate, input_len, options);
766	    defer allocator.free(selections);
767	    return datumTakeNullable(datum, selections);
768	}
