770	/// Generic filter primitive for array/chunked/scalar datums with bool predicates.
771	///
772	/// This preserves the historical array-output shape for compatibility.
773	pub fn datumFilter(datum: Datum, predicate: Datum, options: FilterOptions) KernelError!Datum {
774	    const output_len = try inferBinaryExecLen(datum, predicate);
775	    const allocator = common.inferDatumsAllocator(&[_]Datum{ datum, predicate });
776	    const out_type = datum.dataType();
777	
778	    if (output_len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
779	    if (datum == .array and predicate == .array and options.drop_nulls and output_len <= std.math.maxInt(u32)) {
780	        // drop_nulls: every kept row is a valid index, so the selections are dense u32 (4 B per
781	        // kept row, exact size) and the take runs the branch-free dense kernels.
782	        const pred = predicate.array.data();
783	        if (pred.data_type != .bool or output_len > pred.length) return error.InvalidInput;
784	        var selections: std.ArrayList(u32) = .empty;
785	        defer selections.deinit(allocator);
786	        try appendBoolSelections(allocator, &selections, pred, output_len, 0, options);
787	        return datumTakeArrayLikeNullable(allocator, datum, out_type, @as([]const u32, selections.items));
788	    }
789	    if (datum == .array) {
790	        const selections = try datumFilterSelectionIndices(allocator, predicate, output_len, options);
791	        defer allocator.free(selections);
792	        return datumTakeArrayLikeNullable(allocator, datum, out_type, selections);
793	    }
794	
795	    var pieces: std.ArrayList(ArrayRef) = .empty;
796	    defer {
797	        for (pieces.items) |*piece| piece.release();
798	        pieces.deinit(allocator);
799	    }
800	
801	    switch (predicate) {
802	        // Chunked predicate: use an incremental cursor (O(1) amortized per element)
803	        // instead of calling lookupChunkAt (O(n) per element) inside the loop.
804	        .chunked => |chunks| {
805	            if (chunks.dataType() != .bool) return error.InvalidInput;
806	            var chunk_idx: usize = 0;
807	            var local_idx: usize = 0;
808	            var i: usize = 0;
809	            while (i < output_len) : (i += 1) {
810	                while (chunk_idx < chunks.numChunks() and
811	                    local_idx >= chunks.chunk(chunk_idx).data().length)
812	                {
813	                    chunk_idx += 1;
814	                    local_idx = 0;
815	                }
816	                if (chunk_idx >= chunks.numChunks()) return error.InvalidInput;
817	                const chunk = chunks.chunk(chunk_idx);
818	                const decision: PredicateDecision = if (chunk.data().isNull(local_idx))
819	                    (if (options.drop_nulls) .drop else .emit_null)
820	                else blk: {
821	                    const bool_array = array_mod.BooleanArray{ .data = chunk.data() };
822	                    const keep = bool_array.value(local_idx) catch |err| return mapArrayReadError(err);
823	                    break :blk if (keep) .keep else .drop;
824	                };
825	                local_idx += 1;
826	                const piece = switch (decision) {
827	                    .drop => continue,
828	                    .keep => try accessors.datumElementArrayAt(allocator, datum, i),
829	                    .emit_null => try builders.buildNullLikeArray(allocator, out_type, 1),
830	                };
831	                try appendOwnedArrayRef(allocator, &pieces, piece);
832	            }
833	        },
834	        else => {
835	            var i: usize = 0;
836	            while (i < output_len) : (i += 1) {
837	                const decision = try predicateDecisionAt(predicate, i, options);
838	                const piece = switch (decision) {
839	                    .drop => continue,
840	                    .keep => try accessors.datumElementArrayAt(allocator, datum, i),
841	                    .emit_null => try builders.buildNullLikeArray(allocator, out_type, 1),
842	                };
843	                try appendOwnedArrayRef(allocator, &pieces, piece);
844	            }
845	        },
846	    }
847	
848	    if (pieces.items.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
849	
850	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
851	    return Datum.fromArray(out);
852	}
