16	pub fn concatArrayRefs(
17	    allocator: std.mem.Allocator,
18	    data_type: DataType,
19	    parts: []const ArrayRef,
20	) Error!ArrayRef {
21	    if (parts.len == 0) return error.InvalidInput;
22	
23	    // Flat layouts: two passes over `parts`, each output buffer allocated once; checks part types itself.
24	    if (try concatManyFlat(allocator, data_type, parts)) |out| return out;
25	
26	    for (parts) |part| {
27	        if (!datatype.dataTypeEql(part.data().data_type, data_type)) return error.InvalidInput;
28	    }
29	
30	    if (parts.len == 1) {
31	        // Single part still returns a fresh, compacted copy (offset 0), as before.
32	        var empty = try parts[0].slice(0, 0);
33	        defer empty.release();
34	        return concatTwoArrayRefs(allocator, empty, parts[0]);
35	    }
36	
37	    // Nested/view types: balanced pairwise merge, O(total_len * log(parts.len)).
38	    // ponytail: N-ary list/struct concat (concat children once) if nested concat gets hot.
39	    var level = try mergePairs(allocator, parts);
40	    while (level.items.len > 1) {
41	        const next = mergePairs(allocator, level.items) catch |err| {
42	            releaseAll(allocator, &level);
43	            return err;
44	        };
45	        releaseAll(allocator, &level);
46	        level = next;
47	    }
48	    const out = level.items[0];
49	    level.deinit(allocator);
50	    return out;
51	}
