53	/// Concatenates `refs` two at a time; an odd trailing ref is retained as-is.
54	fn mergePairs(allocator: std.mem.Allocator, refs: []const ArrayRef) Error!std.ArrayList(ArrayRef) {
55	    var out = try std.ArrayList(ArrayRef).initCapacity(allocator, (refs.len + 1) / 2);
56	    errdefer releaseAll(allocator, &out);
57	    var i: usize = 0;
58	    while (i + 1 < refs.len) : (i += 2) {
59	        out.appendAssumeCapacity(try concatTwoArrayRefs(allocator, refs[i], refs[i + 1]));
60	    }
61	    if (i < refs.len) out.appendAssumeCapacity(refs[i].retain());
62	    return out;
63	}
