70	fn concatTwoArrayRefs(
71	    allocator: std.mem.Allocator,
72	    left: ArrayRef,
73	    right: ArrayRef,
74	) Error!ArrayRef {
75	    if (!datatype.dataTypeEql(left.data().data_type, right.data().data_type)) return error.InvalidInput;
76	
77	    if (try concatManyFlat(allocator, left.data().data_type, &[_]ArrayRef{ left, right })) |out| return out;
78	
79	    const dt = left.data().data_type;
80	    const layout_dt = storageDataType(dt);
81	    var merged_storage = try switch (layout_dt) {
82	        .string_view => try concatStringViewArray(allocator, left.data(), right.data()),
83	        .binary_view => try concatBinaryViewArray(allocator, left.data(), right.data()),
84	        .list, .map => try concatListLikeArrayI32(allocator, layout_dt, left.data(), right.data()),
85	        .large_list => try concatListLikeArrayI64(allocator, layout_dt, left.data(), right.data()),
86	        .fixed_size_list => try concatFixedSizeListArray(allocator, layout_dt, left.data(), right.data()),
87	        .struct_ => try concatStructArray(allocator, layout_dt, left.data(), right.data()),
88	        else => error.UnsupportedType,
89	    };
90	
91	    if (datatype.dataTypeEql(dt, layout_dt)) return merged_storage;
92	    const retagged = try retagArrayRefDataType(allocator, merged_storage, dt);
93	    merged_storage.release();
94	    return retagged;
