110	fn concatListLikeArrayI32(
111	    allocator: std.mem.Allocator,
112	    dt: DataType,
113	    left: *const ArrayData,
114	    right: *const ArrayData,
115	) Error!ArrayRef {
116	    try requireBufferCount(left, 2);
117	    try requireBufferCount(right, 2);
118	    if (left.children.len != 1 or right.children.len != 1) return error.InvalidInput;
119	
120	    const total_len = std.math.add(usize, left.length, right.length) catch return error.InvalidInput;
121	    const null_count = std.math.add(usize, try nullCountForArray(left), try nullCountForArray(right)) catch return error.InvalidInput;
122	    const validity = try concatValidityBuffer(allocator, left, right, total_len, null_count);
123	    errdefer if (!validity.isEmpty()) {
124	        var owned = validity;
125	        owned.release();
126	    };
127	
128	    const left_offsets = left.buffers[1].typedSlice(i32) catch return error.InvalidInput;
129	    const right_offsets = right.buffers[1].typedSlice(i32) catch return error.InvalidInput;
130	
131	    const left_last_index = std.math.add(usize, left.offset, left.length) catch return error.InvalidInput;
132	    const right_last_index = std.math.add(usize, right.offset, right.length) catch return error.InvalidInput;
133	    if (left_last_index >= left_offsets.len or right_last_index >= right_offsets.len) return error.InvalidInput;
134	
135	    const left_base = left_offsets[left.offset];
136	    const left_last = left_offsets[left_last_index];
137	    const right_base = right_offsets[right.offset];
138	    const right_last = right_offsets[right_last_index];
139	    if (left_base < 0 or left_last < left_base or right_base < 0 or right_last < right_base) return error.InvalidInput;
140	
141	    const offsets_len = std.math.add(usize, total_len, 1) catch return error.InvalidInput;
142	    var offsets_owned = try buffer.OwnedBuffer.init(allocator, offsets_len * @sizeOf(i32));
143	    var out_offsets = offsets_owned.typedSlice(i32)[0..offsets_len];
144	    out_offsets[0] = 0;
145	
146	    var i: usize = 0;
147	    while (i < left.length) : (i += 1) {
148	        const rel = std.math.sub(i32, left_offsets[left.offset + i + 1], left_base) catch return error.InvalidInput;
149	        out_offsets[i + 1] = rel;
150	    }
151	    const left_prefix = out_offsets[left.length];
152	    while (i < total_len) : (i += 1) {
153	        const right_i = i - left.length;
154	        const rel = std.math.sub(i32, right_offsets[right.offset + right_i + 1], right_base) catch return error.InvalidInput;
155	        out_offsets[i + 1] = std.math.add(i32, left_prefix, rel) catch return error.InvalidInput;
156	    }
157	    var offsets = try offsets_owned.toShared(offsets_len * @sizeOf(i32));
158	    errdefer offsets.release();
159	
160	    const left_child_start = std.math.cast(usize, left_base) orelse return error.InvalidInput;
161	    const left_child_end = std.math.cast(usize, left_last) orelse return error.InvalidInput;
162	    const right_child_start = std.math.cast(usize, right_base) orelse return error.InvalidInput;
163	    const right_child_end = std.math.cast(usize, right_last) orelse return error.InvalidInput;
164	    const left_child_len = std.math.sub(usize, left_child_end, left_child_start) catch return error.InvalidInput;
165	    const right_child_len = std.math.sub(usize, right_child_end, right_child_start) catch return error.InvalidInput;
166	
167	    var left_child = try left.children[0].slice(left_child_start, left_child_len);
168	    defer left_child.release();
169	    var right_child = try right.children[0].slice(right_child_start, right_child_len);
170	    defer right_child.release();
171	    var merged_child = try concatTwoArrayRefs(allocator, left_child, right_child);
172	    errdefer merged_child.release();
173	
174	    const buffers = try allocator.alloc(array_data.SharedBuffer, 2);
175	    errdefer allocator.free(buffers);
176	    buffers[0] = validity;
177	    buffers[1] = offsets;
178	    const children = try allocator.alloc(ArrayRef, 1);
179	    errdefer allocator.free(children);
180	    children[0] = merged_child;
181	
182	    const data = ArrayData{
183	        .data_type = dt,
184	        .length = total_len,
185	        .null_count = null_count,
186	        .buffers = buffers,
187	        .children = children,
188	        .dictionary = null,
189	    };
190	    try data.validateLayout();
191	    return ArrayRef.fromOwnedUnsafe(allocator, data);
192	}
