498	fn flatKind(layout_dt: DataType) Error!?FlatKind {
499	    return switch (layout_dt) {
500	        .null => .null_type,
501	        .bool => .boolean,
502	        .uint8, .int8 => .{ .fixed = 1 },
503	        .uint16, .int16, .half_float => .{ .fixed = 2 },
504	        .uint32, .int32, .float, .date32, .time32, .interval_months, .decimal32 => .{ .fixed = 4 },
505	        .uint64, .int64, .double, .date64, .time64, .timestamp, .duration, .interval_day_time, .decimal64 => .{ .fixed = 8 },
506	        .decimal128, .interval_month_day_nano => .{ .fixed = 16 },
507	        .decimal256 => .{ .fixed = 32 },
508	        .fixed_size_binary => |fsb| .{ .fixed = std.math.cast(usize, fsb.byte_width) orelse return error.InvalidInput },
509	        .string, .binary => .binary32,
510	        .large_string, .large_binary => .binary64,
