515	/// N-ary concat for flat layouts (null, bool, fixed-width, binary/string) in two passes over
516	/// `parts`: one sizing pass (types, rows, bytes, may-have-nulls), then one copy pass that writes
517	/// validity and values of each part together. Nulls are counted once on the output bitmap.
518	/// Returns null for nested and view types, which use the pairwise merge.
519	fn concatManyFlat(allocator: std.mem.Allocator, dt: DataType, parts: []const ArrayRef) Error!?ArrayRef {
520	    const kind = (try flatKind(storageDataType(dt))) orelse return null;
521	
522	    // Copying a DataType for dataTypeEql touches a second cache line of every part's node;
523	    // for parameterless types the tag compare is the whole equality.
524	    const tag_only = switch (dt) {
525	        .null, .bool, .uint8, .int8, .uint16, .int16, .uint32, .int32, .uint64, .int64, .half_float, .float, .double, .string, .binary, .large_string, .large_binary, .date32, .date64 => true,
526	        else => false,
527	    };
528	    var total_len: usize = 0;
529	    var total_data: usize = 0;
530	    var maybe_nulls = false;
531	    for (parts) |part| {
532	        const d = part.data();
533	        if (std.meta.activeTag(d.data_type) != std.meta.activeTag(dt)) return error.InvalidInput;
534	        if (!tag_only and !datatype.dataTypeEql(d.data_type, dt)) return error.InvalidInput;
535	        total_len = std.math.add(usize, total_len, d.length) catch return error.InvalidInput;
536	        maybe_nulls = maybe_nulls or ((d.null_count orelse 1) != 0 and d.buffers.len > 0 and !d.buffers[0].isEmpty());
537	        const r: ByteRange = switch (kind) {
538	            .binary32 => try binaryDataRange(i32, d),
539	            .binary64 => try binaryDataRange(i64, d),
540	            else => .{ .start = 0, .end = 0 },
541	        };
542	        total_data = std.math.add(usize, total_data, r.end - r.start) catch return error.InvalidInput;
543	    }
544	    if (kind == .null_type) {
545	        return try ArrayRef.fromOwnedInlineBuffers(allocator, .{ .data_type = dt, .length = total_len, .null_count = total_len, .buffers = &.{} });
546	    }
547	
548	    // Every output buffer is allocated once. Validity only if some part may hold a null.
549	    const used = bitmap.byteLength(total_len);
550	    const width: usize = switch (kind) {
551	        .fixed => |w| w,
552	        .binary32 => @sizeOf(i32),
553	        .binary64 => @sizeOf(i64),
554	        else => 0,
555	    };
556	    const values_len = switch (kind) {
557	        .boolean => used,
558	        .fixed => std.math.mul(usize, total_len, width) catch return error.InvalidInput,
559	        else => (total_len + 1) * width, // offsets
560	    };
561	    const is_binary = kind == .binary32 or kind == .binary64;
562	    if (total_data > (if (kind == .binary32) @as(usize, std.math.maxInt(i32)) else @as(usize, std.math.maxInt(i64)))) return error.InvalidInput;
563	    var validity = try buffer.OwnedBuffer.init(allocator, if (maybe_nulls) used else 0);
564	    errdefer validity.deinit();
565	    // Bool values are OR-ed bits (need zeroed memory); other slots are all written below.
566	    var values = try (if (kind == .boolean) buffer.OwnedBuffer.init(allocator, values_len) else buffer.OwnedBuffer.initUninit(allocator, values_len + 16));
567	    errdefer values.deinit();
568	    var data_bytes = try buffer.OwnedBuffer.initUninit(allocator, total_data + 16); // wildCopy slack
569	    errdefer data_bytes.deinit();
570	
571	    var row: usize = 0;
572	    var byte_pos: usize = 0;
573	    for (parts) |part| {
574	        const d = part.data();
575	        if (maybe_nulls) try appendValidityBits(validity.data, row, d);
576	        switch (kind) {
577	            .null_type => unreachable,
578	            .boolean => {
579	                try requireBufferCount(d, 2);
580	                try requireBitmapBits(d.buffers[1], d.offset + d.length);
581	                bitmap.copyBits(values.data, row, d.buffers[1].data, d.offset, d.length);
582	            },
583	            .fixed => {
584	                try requireBufferCount(d, 2);
585	                const bytes = try dataBytesForFixedWidth(d, width);
586	                wildCopy(values.data[row * width ..], d.buffers[1].data, d.offset * width, bytes.len);
587	            },
588	            .binary32 => byte_pos = try copyBinaryPart(i32, values.typedSlice(i32), data_bytes.data, row, byte_pos, d),
589	            .binary64 => byte_pos = try copyBinaryPart(i64, values.typedSlice(i64), data_bytes.data, row, byte_pos, d),
590	        }
591	        row += d.length;
592	    }
593	    if (kind == .binary32) values.typedSlice(i32)[0] = 0;
594	    if (kind == .binary64) values.typedSlice(i64)[0] = 0;
595	    const null_count = if (maybe_nulls) total_len - bitmap.countSetBit(validity.data, total_len) else 0;
596	
597	    var bufs: [3]array_data.SharedBuffer = .{ array_data.SharedBuffer.empty, array_data.SharedBuffer.empty, array_data.SharedBuffer.empty };
598	    errdefer for (&bufs) |*b| b.release();
599	    if (null_count == 0) validity.deinit() else bufs[0] = try validity.toShared(used);
600	    bufs[1] = try values.toShared(values_len);
601	    if (is_binary) bufs[2] = try data_bytes.toShared(total_data) else data_bytes.deinit();
602	    const buf_count: usize = if (is_binary) 3 else 2;
603	
604	    const data = ArrayData{
605	        .data_type = dt,
606	        .length = total_len,
607	        .null_count = null_count,
608	        .buffers = bufs[0..buf_count],
609	    };
610	    try data.validateLayout();
611	    return try ArrayRef.fromOwnedInlineBuffers(allocator, data);
612	}
