614	/// Copies `src[lo..][0..n]` to the front of `dst` in 16-byte chunks when both sides have room
615	/// for the rounded-up length (bytes past `n` in `dst` are scratch); else one @memcpy.
616	inline fn wildCopy(dst: []u8, src: []const u8, lo: usize, n: usize) void {
617	    const rounded = (n + 15) & ~@as(usize, 15);
618	    if (n <= 256 and lo + rounded <= src.len and rounded <= dst.len) {
619	        var k: usize = 0;
620	        while (k < n) : (k += 16) dst[k..][0..16].* = src[lo + k ..][0..16].*;
621	    } else @memcpy(dst[0..n], src[lo..][0..n]);
622	}
623	
624	/// Appends one string/binary part: offsets `out_offsets[row + 1 ..]` rebased onto `byte_pos`,
625	/// and its bytes at `out_bytes[byte_pos..]`. Returns the new byte position.
626	fn copyBinaryPart(comptime T: type, out_offsets: []T, out_bytes: []u8, row: usize, byte_pos: usize, d: *const ArrayData) Error!usize {
627	    const r = try binaryDataRange(T, d);
628	    const src = (d.buffers[1].typedSlice(T) catch unreachable)[d.offset .. d.offset + d.length + 1];
629	    // Wrapping math: malformed (non-monotonic) input yields offsets that validateLayout rejects.
630	    const shift: T = @as(T, @intCast(byte_pos)) -% src[0];
631	    for (src[1..], out_offsets[row + 1 ..][0..d.length]) |o, *out| out.* = o +% shift;
632	    wildCopy(out_bytes[byte_pos..], d.buffers[2].data, r.start, r.end - r.start);
633	    return byte_pos + (r.end - r.start);
634	}
635	
636	const ByteRange = struct { start: usize, end: usize };
637	
638	fn binaryDataRange(comptime T: type, d: *const ArrayData) Error!ByteRange {
639	    try requireBufferCount(d, 3);
640	    const offsets = d.buffers[1].typedSlice(T) catch return error.InvalidInput;
641	    const last = std.math.add(usize, d.offset, d.length) catch return error.InvalidInput;
642	    if (last >= offsets.len) return error.InvalidInput;
643	    const start = std.math.cast(usize, offsets[d.offset]) orelse return error.InvalidInput;
644	    const end = std.math.cast(usize, offsets[last]) orelse return error.InvalidInput;
645	    if (end < start or end > d.buffers[2].len()) return error.InvalidInput;
646	    return .{ .start = start, .end = end };
647	}
648	
649	fn nullCountForArray(data: *const ArrayData) ConcatArrayError!usize {
650	    if (data.null_count) |count| return count;
651	    if (data.validity()) |v| {
652	        const end = data.offset + data.length;
653	        if (bitmap.byteLength(end) > v.data.len) return error.InvalidInput;
654	        return bitmap.countUnsetBitsInRange(v.data, data.offset, end);
655	    }
656	    return 0;
657	}
658	
659	fn concatValidityBuffer(
660	    allocator: std.mem.Allocator,
661	    left: *const ArrayData,
662	    right: *const ArrayData,
663	    total_len: usize,
664	    total_nulls: usize,
665	) ConcatArrayError!array_data.SharedBuffer {
666	    if (total_nulls == 0) return array_data.SharedBuffer.empty;
667	    const used = bitmap.byteLength(total_len);
668	    var owned = try buffer.OwnedBuffer.init(allocator, used);
669	    errdefer owned.deinit();
670	    try appendValidityBits(owned.data, 0, left);
671	    try appendValidityBits(owned.data, left.length, right);
672	    return owned.toShared(used);
673	}
674	
675	/// Writes `data`'s validity bits into zeroed `dst` at bit `dst_off` (all-null parts stay zero).
676	fn appendValidityBits(dst: []u8, dst_off: usize, data: *const ArrayData) ConcatArrayError!void {
677	    if (data.length == 0) return;
678	    if (data.null_count) |count| {
679	        if (count == data.length) return;
680	        if (count == 0) return bitmap.setBits(dst, dst_off, data.length);
681	    }
682	    // Every caller's layout has a top-level bitmap, so read buffers[0] directly (cheaper than validity()).
683	    if (data.buffers.len == 0 or data.buffers[0].isEmpty()) return bitmap.setBits(dst, dst_off, data.length);
684	    const bits = data.buffers[0].data;
685	    if (bitmap.byteLength(data.offset + data.length) > bits.len) return error.InvalidInput;
686	    bitmap.copyBits(dst, dst_off, bits, data.offset, data.length);
687	}
688	
689	fn dataBytesForFixedWidth(data: *const ArrayData, byte_width: usize) ConcatArrayError![]const u8 {
690	    const start = std.math.mul(usize, data.offset, byte_width) catch return error.InvalidInput;
691	    const data_len = std.math.mul(usize, data.length, byte_width) catch return error.InvalidInput;
692	    const end = std.math.add(usize, start, data_len) catch return error.InvalidInput;
693	    if (data.buffers.len < 2) return error.InvalidInput;
694	    if (end > data.buffers[1].len()) return error.InvalidInput;
695	    return data.buffers[1].data[start..end];
696	}
697	
698	fn requireBufferCount(data: *const ArrayData, min_count: usize) ConcatArrayError!void {
699	    if (data.buffers.len < min_count) return error.InvalidInput;
700	}
701	
702	fn requireBitmapBits(buf: array_data.SharedBuffer, bit_len: usize) ConcatArrayError!void {
703	    if (bitmap.byteLength(bit_len) > buf.len()) return error.InvalidInput;
704	}
