# usage: prof.sh <exe> <runs>: min over runs of each PROF field and ns_per_row, per benchmark line order
exe=$1; n=${2:-5}
for i in $(seq 1 $n); do $exe 2>&1; done | awk '
/^PROF/ { k++; key="p" (k%2); for (f=2; f<=5; f++) { split($f, kv, "="); v=kv[2]+0; id=key kv[1]; if (!(id in m) || v < m[id]) m[id]=v } }
/^benchmark=/ { match($0, /benchmark=[a-z_]*/); name=substr($0, RSTART+10, RLENGTH-10); match($0, /ns_per_row=[0-9.]*/); v=substr($0, RSTART+11, RLENGTH-11)+0; if (!(name in b) || v < b[name]) b[name]=v }
END { for (id in m) printf "%s=%d ", id, m[id]; print ""; for (x in b) printf "%s min=%.2f\n", x, b[x] }'

